# analyzer_digest() of the installed release (/opt/infer or /opt/infersharp). It is unpacked from the
# archive above, so the value is the same on every machine: `warmup.py --downloads DIR --digests`
# unpacks every release and compares. Computing it takes under a second (1 to 1.6 GB for Infer).
ANALYZER_TREES = {
    'Infer 0.16.0': 'a958b10ee4b8203a29a681e42369ba8dc6d4227b96ae47ed6f3267087fe5d7fc',
    'Infer 0.17.0': 'b0623e977d9b17903cb1a88be79f6f01d8d265c56449daffd35da7213cfc3b51',
    'Infer 1.0.0': 'a4801c424ec78fed5fd1e9b320f03d33619dbc62435bbf12c693b4717036c184',
    'Infer 1.1.0': 'ef903215e1026129b5a5613b3299582ced7370a254ceb336fabd532654a533ae',
    'InferSharp 1.2': '1d23e607b6479435a5201777cc9eb5460fdde6a51615c2a655184c6ebfd5525e',
    'InferSharp 1.3': 'b88a7cb3c1f40529bd48c2ff9e505610a34f6b9433a2664e93e7917c33f0fe88',
    'InferSharp 1.4': '25def6014ff6dd9c1dfe91dd59afaefe0ccc163eb45972b441d14287dd5e2400',
    'InferSharp 1.5': 'af7c673f9b7bfd730810b3e63068a9fd0444ccc80f174d90d1192464bd786888',
}
ANALYZER_ROOTS = {'Infer': '/opt/infer', 'InferSharp': '/opt/infersharp'}
# A runner may mount, read-only, an archive of /cache (Maven, NuGet, Gradle) from an earlier build
# of the task: the build scripts unpack it once into the empty /cache, and the verifier empties
# /cache and unpacks it again, so that it does not build with what the agent left there. Without
# the archive everything is downloaded, and the verifier's build reuses the agent's /cache.
DEPENDENCY_ARCHIVE = '/opt/inferredbugs/dependencies.tar'    # or the path in INFERREDBUGS_DEPENDENCY_CACHE
DEPENDENCY_MARKER = '/cache/.inferredbugs-dependencies'


def analyzer_digest(root, name=None):
    """One SHA-256 over an installed analyzer: of every file under `root` its path (as if root were
    `name`), whether it is executable and its content, of a link its target. A file added, removed
    or changed gives another value; None when there is no such directory."""
    import hashlib
    if not os.path.isdir(root):
        return None
    entries = []
    for directory, dirs, files in os.walk(root):
        for entry in dirs + files:
            path = os.path.join(directory, entry)
            if os.path.islink(path) or not os.path.isdir(path):
                entries.append(path)
    total = hashlib.sha256()
    for path in sorted(entries):
        if os.path.islink(path):
            kind, value = 'link', hashlib.sha256(os.fsencode(os.readlink(path))).hexdigest()
        elif os.path.isfile(path):
            content = hashlib.sha256()
            with open(path, 'rb') as f:
                for block in iter(lambda: f.read(1 << 20), b''):
                    content.update(block)
            kind, value = ('exec' if os.stat(path).st_mode & 0o111 else 'file'), content.hexdigest()
        else:
            kind, value = 'other', ''
        total.update(os.fsencode('%s\0%s\0%s\n' % ((name or root) + path[len(root):], kind, value)))
    return total.hexdigest()


_INSTALL_HEAD = r'''#!/bin/bash
# Generated by patch.py.
# Installs {analyzer}, the static analyzer that reports this task's warning, into /opt
# (needs root and network access). Every download is checked against its SHA-256.
# Usage: bash install_analyzer.sh [--force]     --force reinstalls from scratch
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
STAMP=/opt/inferredbugs-analyzer
if [ "${{1:-}}" != --force ] && [ "$(cat "$STAMP" 2>/dev/null)" = "{analyzer}" ]; then
  echo "{analyzer} is already installed"; exit 0
fi
rm -rf "$STAMP" /opt/infer /opt/infersharp /usr/local/bin/infer
fetch() {{   # URL SHA256 FILE
  local attempt
  # INFERREDBUGS_DOWNLOAD_CACHE: a directory of files named by their SHA-256 (see warmup.py)
  if [ -n "${{INFERREDBUGS_DOWNLOAD_CACHE:-}}" ] && [ -f "$INFERREDBUGS_DOWNLOAD_CACHE/$2" ]; then cp "$INFERREDBUGS_DOWNLOAD_CACHE/$2" "$3" && return 0; fi
  for attempt in 1 2 3 4 5; do
    if curl -fLsS --retry 3 --connect-timeout 20 "$1" -o "$3" && echo "$2  $3" | sha256sum -c --quiet -; then return 0; fi
    sleep $((attempt * 10 + RANDOM % 10))
  done
  echo "cannot download $1" >&2; return 1
}}
packages() {{
  # apt downloads as a second user into directories the image made for that user. A container
  # that maps a single user (apptainer --fakeroot) has no such user and cannot write there:
  # download as root into directories of our own.
  local apt="apt-get -o APT::Sandbox::User=root -o Dir::Cache::Archives=$work/apt/archives -o Dir::State::Lists=$work/apt/lists"
  mkdir -p "$work/apt/archives/partial" "$work/apt/lists/partial"
  $apt update >/dev/null && $apt install -y --no-install-recommends "$@" >/dev/null
}}
work=$(mktemp -d); trap 'rm -rf "$work"' EXIT
'''
_INSTALL_PYTHON2 = r'''# The capture of this Infer release is written in Python 2.7, which the Java images carry.
[ -x /opt/python2/bin/python2.7 ] || { echo "Python 2.7 is missing: this analyzer runs on the task's Java image" >&2; exit 1; }
'''
_INSTALL_INFER = r'''command -v xz >/dev/null || packages xz-utils
fetch https://github.com/facebook/infer/releases/download/v{version}/infer-linux64-v{version}.tar.xz {sha256} "$work/infer.tar.xz"
mkdir -p /opt/infer && tar -xJf "$work/infer.tar.xz" --strip-components=1 -C /opt/infer
# (no compiled Python files next to the release's own: the verifier compares the directory with the release)
printf '#!/bin/sh\nPATH=/opt/python2/bin:/opt/infer/bin:$PATH PYTHONDONTWRITEBYTECODE=1 exec /opt/infer/bin/infer "$@"\n' > /usr/local/bin/infer && chmod +x /usr/local/bin/infer
/opt/infer/bin/infer --version | head -1
'''
_INSTALL_INFERSHARP = r'''# Its Infer needs a time zone database (without one, capture aborts formatting the run time).
[ -d /usr/share/zoneinfo ] || packages tzdata
fetch https://github.com/microsoft/infersharp/releases/download/v{version}/infersharp-linux64-v{version}.tar.gz {sha256} "$work/infersharp.tgz"
tar -xzf "$work/infersharp.tgz" -C /opt && echo {version} > /opt/infersharp/VERSION
/opt/infersharp/infer/lib/infer/infer/bin/infer --version | head -1
'''
# Cilsil, the translator of InferSharp 1.2 and 1.3, runs on .NET 5 (1.4 and 1.5: .NET 6, which
# takes OpenSSL 3). That runtime loads OpenSSL 1.x
# as soon as an assembly makes it hash or verify something, and aborts without it ("No usable
# version of libssl was found"); the Debian 12 images carry only OpenSSL 3. The two libraries come
# from Debian 11's package, by hash (LIBSSL1), and are only added: nothing of the image is replaced.
LIBSSL1 = ('https://snapshot.debian.org/archive/debian/20231003T205808Z/pool/main/o/openssl/libssl1.1_1.1.1w-0+deb11u1_amd64.deb',
           'aadf8b4b197335645b230c2839b4517aa444fd2e8f434e5438c48a18857988f7')
_INSTALL_LIBSSL1 = r'''# Its translator runs on .NET 5, which needs OpenSSL 1.x (this image has only OpenSSL 3).
if ! ls /usr/lib/x86_64-linux-gnu/libssl.so.1.* /usr/lib64/libssl.so.1.* >/dev/null 2>&1; then
  fetch {url} {sha256} "$work/libssl1.1.deb"
  dpkg-deb -x "$work/libssl1.1.deb" "$work/libssl1.1"
  mkdir -p /usr/lib/x86_64-linux-gnu
  cp -a "$work/libssl1.1/usr/lib/x86_64-linux-gnu/libssl.so.1.1" "$work/libssl1.1/usr/lib/x86_64-linux-gnu/libcrypto.so.1.1" /usr/lib/x86_64-linux-gnu/
fi
'''


def analyzer_release(analyzer: str) -> str:
    """'InferSharp 1.3 biabduction' is release 'InferSharp 1.3' with another checker."""
    return ' '.join(analyzer.split()[:2])


def install_analyzer_script(analyzer: str) -> bytes:
    release = analyzer_release(analyzer)
    kind, version = release.split()
    body = _INSTALL_HEAD.format(analyzer=release)
    if kind == 'Infer':
        body += (_INSTALL_PYTHON2 if version.startswith('0.') else '') + _INSTALL_INFER.format(version=version, sha256=ANALYZERS[release])
    else:
        body += _INSTALL_INFERSHARP.format(version=version, sha256=ANALYZERS[release])
        if tuple(map(int, version.split('.'))) < (1, 4):
            body += _INSTALL_LIBSSL1.format(url=LIBSSL1[0], sha256=LIBSSL1[1])
    return (body + 'echo "' + release + '" > "$STAMP"\n').encode()


# --------------------------------------------------------------------------- task verifier
