def embedded_warnings() -> dict:
    import lzma
    global _WARNINGS
    if _WARNINGS is None:
        text = ''.join(EMBEDDED_WARNINGS.split())
        _WARNINGS = json.loads(lzma.decompress(base64.b85decode(text))) if text else {}
    return _WARNINGS


_WARNINGS = None
_TIMES = None


def verification_times(task_id: str) -> dict | None:
    """Measured seconds of the packaged verifier on the buggy file ('build': setup and build under
    the analyzer, 'analyze'), from the archived warning-identity audit/verification-times.json."""
    global _TIMES
    if _TIMES is None:
        path = Path(__file__).resolve().parent / 'warning_identity/verification-times.json'
        _TIMES = json.loads(path.read_text())['tasks'] if path.exists() else {}
    return _TIMES.get(task_id)


def task_timeouts(task_id: str) -> tuple[int, int]:
    """(agent, verifier) seconds, from the measured build and analysis of the task (the original
    TaskTrove tasks have 900 and 720 for every task). The agent fetches the project, installs the
    analyzer and builds a few times: six builds, at least half an hour. The verifier fetches,
    installs, builds and analyzes, twice when other files changed: three times build plus
    analysis, at least a quarter of an hour. Within the default --max-verify-seconds (300) every
    task gets the floors: 1800 and 900."""
    t = verification_times(task_id)
    if not t:
        return 1800, 900
    return (min(14400, max(1800, 6 * t['build'])), min(10800, max(900, 3 * (t['build'] + t['analyze']))))


# A submission's changed files are all taken over (see submitted_changes). Warnings are compared
# in the changed source files of the task's language.
SOURCE_SUFFIXES = {'java': ('.java',), 'csharp': ('.cs',)}
# Directories of build products: new files in one that the checkout does not have are left behind
# (a stale product would make the build skip the compiler, and Infer sees only what is compiled).
BUILD_DIRECTORIES = ('target', 'build', 'bin', 'obj', 'out', 'packages', 'node_modules', '.gradle', '.git', '.audit-binaries')
# The analyzer's own configuration stays the checkout's: it can switch warnings off.
ANALYZER_CONFIGURATION = ('.inferconfig',)


def warning_key(warning, file=None):
    """What identifies a warning for the verifier: Infer's issue hash. Infer leaves the numbers of
    'line 12', 'column 3', 'parameter 2' and '$4' out of it, so a warning keeps its hash when code
    above it moves. InferSharp's resource leaks say 'at Line 120', which Infer does not recognise:
    their hash changes with every line added or removed above (of the stored warnings, all 85
    pairs that differ only in these numbers have different hashes; all 198 pairs that differ only
    in 'line N' have the same). For such a message the key is a hash of our own over what Infer
    hashes, without those numbers. `file`: for a stored warning, which has no file of its own."""
    import hashlib
    qualifier = warning.get('qualifier') or ''
    if not re.search(r'\bLine \d+', qualifier):
        return warning.get('hash')
    text = '|'.join((warning.get('bug_type') or '', warning.get('procedure') or '', os.path.basename(file or warning.get('file') or ''),
                     re.sub(r'\bLine \d+', 'Line _', qualifier)))
    return 'line-free:' + hashlib.md5(text.encode()).hexdigest()


# The verifier and the agent's analyze.sh are one generated script (VERIFIER_MAIN below the functions
# it shares with the warning audit), so the task is graded by the code that audited it.
VERIFIER_MAIN = r'''

# ----------------------------------------------------------------------------- driver
HERE = Path(__file__).resolve().parent
TASK = json.loads((HERE / 'task.json').read_text())
PREFIX = ('unset MAVEN_CONFIG; export IB_REAL_MVN=$(type -P mvn || true); '
          'mvn() { python3 %(files)s/maven_transport.py "$IB_REAL_MVN" "$@"; }; '
          'audit_mvn_transport() { python3 %(files)s/maven_transport.py "$@"; }; export -f mvn audit_mvn_transport; ')


class Run:
    def __init__(self, workspace, logs, timeout, setup, scope=(), analysis_timeout=None):
        self.ws, self.logs, self.timeout, self.setup = Path(workspace), Path(logs), timeout, setup
        # the analysis has a limit of its own: it is not what a build limit is about
        self.analysis_timeout = analysis_timeout or timeout
        # the files whose warnings are wanted: the target and the other source files of a submission
        self.scope = [TASK['target_file']] + [f for f in scope if f != TASK['target_file']]
        # the audit's way to collect the warnings of every file (INFERREDBUGS_WHOLE_PROJECT=1)
        self.whole = os.environ.get('INFERREDBUGS_WHOLE_PROJECT') == '1'
        self.logs.mkdir(parents=True, exist_ok=True)
        self.files = HERE.parent                       # /tests or /setup_files
        # Infer's working directory (the audit's /audit) lives outside /logs/verifier: its database
        # grows to hundreds of MB on large projects, and a verifier that is killed cannot clean up;
        # the runner then fails to fetch the log directory and the trial has no result at all
        # (jobs 924999-925011, 2026-10-03). Only report.json and the step logs are kept under logs.
        self.out = Path(tempfile.mkdtemp(prefix='inferredbugs-verifier-', dir=os.environ.get('TMPDIR') or '/tmp')) / 'infer'
        self.fixture = self.out / 'fixture'            # the audit's /fixture
        self.fixture.mkdir(parents=True)
        self.result = {'task_id': TASK['task_id'], 'analyzer': TASK['analyzer'], 'steps': {}, 'status': 'started'}
        java = TASK['language'] == 'java'
        build = self.files / ('build.capture.sh' if java else 'build.sh')
        for name, text in (('capture.sh', AUDIT_CAPTURE_SH), ('audit_capture.py', AUDIT_CAPTURE_PY), ('javac-shim', AUDIT_JAVAC_SHIM),
                           ('infer-javac', AUDIT_INFER_JAVAC), ('csharp-build.sh', AUDIT_CSHARP_BUILD_SH)):
            (self.fixture / name).write_text(self.localize(text, build))
        shutil.copy2(self.files / 'maven_transport.py', self.fixture / 'maven_transport.py')

    def localize(self, text, build=None):
        """The audit ran every task at fixed mount points; here they are directories."""
        # in one pass: a replacement may itself contain one of the names
        names = {'/fixture/': str(self.fixture) + '/', '/audit/': str(self.out) + '/', '/workspace': str(self.ws)}
        if build:
            names['/tests/build.sh /workspace'] = '%s %s' % (build, self.ws)
        return re.sub('|'.join(map(re.escape, sorted(names, key=len, reverse=True))), lambda m: names[m.group(0)], text)

    def stage(self, name, shell):
        env = dict(os.environ, INFERREDBUGS_TRANSPORT_ACTIVE='1', TMPDIR=os.environ.get('TMPDIR', '/tmp'))
        env.setdefault('HOME', '/tmp/home')
        env['PATH'] = '/opt/python2/bin:/opt/infer/bin:' + env.get('PATH', '/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin')
        # a runner's own PATH may lack the image's JDK (see the build scripts)
        if shutil.which('javac', path=env['PATH']) is None:
            for home in [env.get('JAVA_HOME', ''), '/opt/java/openjdk'] + sorted(map(str, Path('/usr/lib/jvm').glob('*'))):
                if home and os.access(os.path.join(home, 'bin/javac'), os.X_OK):
                    env['JAVA_HOME'], env['PATH'] = home, os.path.join(home, 'bin') + ':' + env['PATH']
                    break
        # Infer's capture is Python: compiled files next to its sources would make the installed
        # analyzer differ from the release (installed_analyzer), and the verifier install it again.
        env['PYTHONDONTWRITEBYTECODE'] = '1'
        if TASK['language'] == 'java':
            env['JAVA_TOOL_OPTIONS'] = (env.get('JAVA_TOOL_OPTIONS', '') + ' ' + AUDIT_NO_REFORMAT).strip()
        start = time.monotonic()
        with (self.logs / (name + '.log')).open('wb') as log:
            proc = subprocess.Popen(['bash', '-c', PREFIX % {'files': self.fixture} + shell], stdout=log, stderr=subprocess.STDOUT,
                                    env=env, cwd=str(self.ws), start_new_session=True)
            try:
                code, timed_out = proc.wait(timeout=self.analysis_timeout if name in ('translate', 'capture_inventory', 'analyze') else self.timeout), False
            except subprocess.TimeoutExpired:
                os.killpg(proc.pid, signal.SIGKILL); proc.wait(); code, timed_out = -9, True
        self.result['steps'][name] = {'exit_code': code, 'timeout': timed_out, 'seconds': round(time.monotonic() - start, 1)}
        if code:
            self.result['status'] = name + ('_timeout' if timed_out else '_failed')
        return not code

    def in_scope(self, path):
        return self.whole or any(warning_audit_file(f, path) for f in self.scope)

    def java(self, target):
        r, out = self.result, self.out
        warning_audit_strip_formatters(self.ws)
        for properties in self.ws.rglob('maven-wrapper.properties'):
            properties.write_text(properties.read_text().replace('https://repo1.maven.org/maven2/', 'https://repo.maven.apache.org/maven2/'))
        if self.setup and not self.stage('setup', 'bash %s/build_setup.sh %s' % (self.files, self.ws)):
            return None
        if not self.stage('capture', 'bash %s/capture.sh' % self.fixture):
            status = r['status']
            r['compiles'] = self.stage('build', 'bash %s/build.sh %s' % (self.files, self.ws))
            r['status'] = status if r['compiles'] else 'build_failed'
            return None
        r['compiles'] = True
        database = out / 'infer-out/results.db'
        if not database.exists():
            r['status'] = 'no_capture_database'; return None
        changed = out / 'changed.txt'
        cap = sqlite3.connect(str(database))
        if 'proc_name_hum' in {row[1] for row in cap.execute('PRAGMA table_info(procedures)')}:
            procedures = cap.execute('SELECT proc_name_hum,source_file,cfg IS NOT NULL FROM procedures').fetchall(); cap.close()
            captured = [(p, f, c) for p, f, c in procedures if c and self.in_scope(f)]
        else:
            cap.close()
            inventory = out / 'capture_inventory.full'
            if not self.stage('capture_inventory', 'infer debug --procedures --procedures-name -o %s/infer-out > %s' % (out, inventory)):
                return None
            captured = [(p, f, c) for p, f, c in warning_audit_captured_procedures(inventory.read_text(errors='replace')) if self.in_scope(f)]
            inventory.unlink()
        r['target_procedures'] = [p for p, f, c in captured if warning_audit_file(target, f)]
        if not r['target_procedures']:
            r['status'] = 'target_not_captured'; return None
        # Analyze the file Infer captured: a preprocessed copy may stand in for the source.
        changed.write_text(''.join(sorted({str(self.ws / f) + '\n' for p, f, c in captured})))
        # In a whole project Infer meets code it fails on; --keep-going skips that procedure.
        restrict = '--keep-going ' if self.whole else '--changed-files-index %s ' % changed
        # Infer gives up on a method after a number of symbolic steps or of elapsed seconds. The
        # seconds make the result depend on the machine's load (on a busy node the task's warning
        # went missing and the buggy file passed); only the steps remain.
        options = '--seconds-per-iteration 1000000 ' + os.environ.get('INFERREDBUGS_ANALYZE_OPTIONS', '')
        if not self.stage('analyze', 'infer analyze -j %s --racerd --racerd-guardedby --immutable-cast --printf-args %s%s-o %s/infer-out' % (os.environ.get('INFERREDBUGS_ANALYSIS_JOBS', '1'), options.strip() + ' ', restrict, out)):
            return None
        return out / 'infer-out/report.json'

    def csharp(self, target):
        r, out, root = self.result, self.out, '/opt/infersharp'
        if self.setup and not self.stage('setup', 'bash %s/build_setup.sh %s' % (self.files, self.ws)):
            return None
        started = time.time() - 2
        if not self.stage('build', 'bash %s/csharp-build.sh' % self.fixture):
            return None
        r['compiles'] = True
        bundle = self.ws / '.audit-binaries'
        shutil.rmtree(bundle, ignore_errors=True)
        chosen, holds_target, fields = warning_audit_assemblies((self.ws, Path('/tmp')), target, started, bundle, Path('/'))
        r.update(fields)
        if not chosen:
            r['status'] = 'no_assemblies'; return None
        release = TASK['analyzer'].split()[1]
        config = out / 'analyzer-config.json'
        if release == '1.5':
            translate = 'cd %s; ./Cilsil/Cilsil translate %s --outcfg %s/cfg.json --outtenv %s/tenv.json --extprogress' % (root, bundle, out, out)
            analyze = 'cd %s; INFERCONFIG=%s %s/infer/lib/infer/infer/bin/infer run -j 1 -o %s/infer-out --cfg-json %s/cfg.json --tenv-json %s/tenv.json' % (root, config, root, out, out, out)
            extra = ['NULL_DEREFERENCE', 'STACK_VARIABLE_ADDRESS_ESCAPE']
        else:
            translate, analyze = warning_audit_legacy_infersharp('infersharp-v' + release, 'biabduction' in TASK['analyzer'], root, str(bundle), str(out))
            extra = ['STACK_VARIABLE_ADDRESS_ESCAPE']
        if 'INFERCONFIG=' in analyze:
            # The release's defaults suppress warning types the dataset contains.
            value = json.loads(Path(root, '.inferconfig').read_text())
            value['enable-issue-type'] = sorted(set(value.get('enable-issue-type', []) + value.get('disable-issue-type', []) + extra))
            value['disable-issue-type'] = []
            config.write_text(json.dumps(value, indent=2))
        if not self.stage('translate', translate):
            return None
        if not ((out / 'cfg.json').exists() and (out / 'tenv.json').exists()) and holds_target:
            # Cilsil aborts on one unsupported method anywhere (and still exits 0). Translate only
            # the assemblies that hold the target; the rest stay in the bundle, without symbols.
            r['translate_scope'] = 'target_assemblies'
            for name, p in chosen.items():
                if p not in holds_target:
                    for x in (bundle / Path(name).with_suffix('.pdb').name, bundle / (name + '.mdb')):
                        if x.exists(): x.unlink()
            if not self.stage('translate', translate):
                return None
        if not ((out / 'cfg.json').exists() and (out / 'tenv.json').exists()):
            r['status'] = 'translate_crashed'; return None
        captured = []
        for proc in json.loads((out / 'cfg.json').read_text()).get('procs', {}).values():
            a = proc['pd_attributes']; f = a.get('loc', {}).get('source_file', {}).get('path', ''); pn = a['proc_name']
            if a.get('is_defined') and warning_audit_file(target, f):
                captured.append(pn['class_name'] + '.' + pn['method_name'] + '()')
        r['target_procedures'] = captured
        if not captured:
            r['status'] = 'target_not_captured'; return None
        if not self.stage('analyze', analyze):
            return None
        return out / 'infer-out/report.json'

    def analyze(self):
        """The warnings of the files in scope, or None with the reason in result['status']."""
        target = TASK['target_file']
        source = self.ws / target
        if not source.is_file():
            self.result['status'] = 'target_missing'; return None
        content = source.read_bytes()
        try:
            report = (self.java if TASK['language'] == 'java' else self.csharp)(target)
            if report is None:
                return None
            if not (source.is_file() and source.read_bytes() == content):
                self.result['status'] = 'source_modified_by_recipe'; return None
            if not report.exists():
                self.result['status'] = 'missing_report'; return None
            rows = json.loads(report.read_text())
            shutil.copy2(report, self.logs / 'report.json')
            self.result['status'] = 'analyzed'
            return [w for w in rows if self.in_scope(w.get('file', ''))]
        finally:
            shutil.rmtree(self.out / 'infer-out', ignore_errors=True)
            shutil.rmtree(self.ws / '.audit-binaries', ignore_errors=True)
            for name in ('cfg.json', 'tenv.json'):
                if (self.out / name).exists(): (self.out / name).unlink()


def brief(w):
    return dict({k: w.get(k) for k in ('bug_type', 'file', 'procedure', 'line', 'qualifier', 'hash')}, key=warning_key(w))


def git(directory, work_tree, *args):
    command = ['git', '--git-dir', str(directory), '--work-tree', str(work_tree), '-c', 'core.fileMode=false', '-c', 'core.autocrlf=false',
               '-c', 'core.quotePath=false', '-c', 'safe.directory=*', '-c', 'user.name=verifier', '-c', 'user.email=verifier@localhost',
               '-c', 'gc.auto=0', *args]
    return subprocess.run(command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(work_tree)).stdout


def submitted_changes(submission, checkout, scratch):
    """The files in which the submission differs from the checkout, as if the agent had committed
    them on top of it: {path: 'modified' | 'added' | 'deleted'}. The checkout is committed to a
    scratch repository and the submission is its work tree, so the project's own .gitignore keeps
    build products out. Never taken over: directories of build products the checkout does not have,
    and an analyzer configuration. Deletions count only when the submission is a whole project (an
    agent may also have written just the file it was asked for)."""
    directory = Path(scratch) / 'changes.git'
    shutil.rmtree(str(directory), ignore_errors=True)
    subprocess.run(['git', 'init', '-q', '--bare', str(directory)], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    git(directory, checkout, 'add', '-A', '-f', '.')
    git(directory, checkout, 'commit', '-q', '--allow-empty', '-m', 'checkout')
    tracked = git(directory, checkout, 'ls-files', '-z').decode(errors='surrogateescape').split('\0')[:-1]
    fields = git(directory, submission, 'status', '--porcelain', '-z', '--untracked-files=all', '--no-renames').decode(errors='surrogateescape').split('\0')[:-1]
    shutil.rmtree(str(directory), ignore_errors=True)
    changes, missing = {}, []
    for field in fields:
        state, rel = field[:2], field[3:]
        parts = PurePosixPath(rel).parts
        if parts[-1] in ANALYZER_CONFIGURATION or '.git' in parts or (Path(submission) / rel).is_symlink():
            continue
        if 'D' in state:
            missing.append(rel)
        elif '?' in state or 'A' in state:
            if not any(part in BUILD_DIRECTORIES and not (Path(checkout) / Path(*parts[:i + 1])).is_dir() for i, part in enumerate(parts[:-1])):
                changes[rel] = 'added'
        else:
            changes[rel] = 'modified'
    if tracked and len(missing) * 2 < len(tracked):
        changes.update({rel: 'deleted' for rel in missing})
    return changes


def is_source(rel):
    return rel.endswith(SOURCE_SUFFIXES[TASK['language']])


def apply_changes(changes, submission, checkout):
    for rel, kind in changes.items():
        destination = checkout / rel
        if kind == 'deleted':
            if destination.is_file() or destination.is_symlink():
                destination.unlink()
        else:
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(str(submission / rel), str(destination))


def installed_analyzer(logs, timeout):
    """'image' when the installed analyzer is the release, file by file (the task image carries it,
    and the agent can change it); otherwise it is installed from scratch: 'verifier', or None when
    that failed."""
    root = ANALYZER_ROOTS[TASK['analyzer'].split()[0]]
    found = analyzer_digest(root)
    if found == TASK['analyzer_tree']:
        return 'image'
    with (logs / 'install.log').open('wb') as log:
        log.write(('%s is not the release (%s), installing it again\n' % (root, found or 'missing')).encode())
        log.flush()
        code = subprocess.run(['timeout', str(timeout), 'bash', str(HERE.parent / 'install_analyzer.sh'), '--force'],
                              stdout=log, stderr=subprocess.STDOUT).returncode
    return None if code else 'verifier'


def clean_dependencies():
    """'archive' when the runner mounts the task's dependency archive: /cache is emptied and filled
    from it, so the verifier builds with nothing the agent put there (what the archive lacks is
    downloaded). 'reused' without an archive: the build uses /cache as the agent left it."""
    archive = os.environ.get('INFERREDBUGS_DEPENDENCY_CACHE') or DEPENDENCY_ARCHIVE
    cache = os.path.dirname(DEPENDENCY_MARKER)
    if not os.path.isfile(archive) or not os.path.isdir(cache):
        return 'reused'
    for entry in os.listdir(cache):
        path = os.path.join(cache, entry)
        if os.path.isdir(path) and not os.path.islink(path):
            shutil.rmtree(path, ignore_errors=True)
        else:
            os.unlink(path)
    if subprocess.run(['tar', '-xf', archive, '-C', cache], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode:
        return 'archive_unreadable'       # an empty /cache: everything is downloaded
    Path(DEPENDENCY_MARKER).touch()
    return 'archive'


def main():
    ap = argparse.ArgumentParser(description='Run the task\'s static analyzer on the target file, as the verifier does.')
    ap.add_argument('--workspace', default='/app', help='project directory (setup and build run in it)')
    ap.add_argument('--logs', default='/tmp/inferredbugs-analysis')
    ap.add_argument('--timeout', type=int, default=5400, help='seconds per build step')
    ap.add_argument('--analysis-timeout', type=int, help='seconds per analysis step (default: as --timeout)')
    ap.add_argument('--setup', action='store_true', help='run build_setup.sh first (a fresh checkout)')
    ap.add_argument('--grade', help='verifier: the submitted project directory; its source changes are applied to --workspace (a fresh '
                                    'checkout with the buggy target) and the warnings compared with task.json')
    a = ap.parse_args()
    logs, target = Path(a.logs), TASK['target_file']
    logs.mkdir(parents=True, exist_ok=True)
    others, elsewhere, baseline = [], set(), None
    if a.grade:
        analyzer = installed_analyzer(logs, a.timeout)
        if analyzer is None:
            print('the analyzer could not be installed (%s)' % (logs / 'install.log'), file=sys.stderr)
            return 1
        dependencies = clean_dependencies()
        changes = submitted_changes(Path(a.grade), Path(a.workspace), logs)
        # warnings are compared in the changed source files; any changed file is taken over
        others = sorted(rel for rel in changes if rel != target and is_source(rel))
        if others:
            # What the analyzer says about those files before the submission: on a copy, since a
            # second build in one directory would skip what is already compiled.
            baseline = Path(str(Path(a.workspace)) + '-baseline')
            shutil.rmtree(str(baseline), ignore_errors=True)
            shutil.copytree(str(a.workspace), str(baseline), symlinks=True)
            before = Run(baseline, logs / 'baseline', a.timeout, a.setup, [rel for rel in others if changes[rel] != 'added'], a.analysis_timeout)
            known = before.analyze()
            shutil.rmtree(str(baseline), ignore_errors=True)
            if known is None:
                result = dict(before.result, status='baseline_' + before.result['status'], reward=0)
                (logs / 'result.json').write_text(json.dumps(result, indent=2) + '\n')
                print(json.dumps({'status': result['status'], 'reward': 0}, indent=2))
                return 1
            elsewhere = {warning_key(w) for w in known if not warning_audit_file(target, w.get('file', ''))}
            # kept in result.json: what the other files had before, and what a second build costs
            baseline = {'steps': before.result['steps'], 'warnings': [brief(w) for w in known]}
        apply_changes(changes, Path(a.grade), Path(a.workspace))
    run = Run(a.workspace, logs, a.timeout, a.setup, [rel for rel in others if changes[rel] != 'deleted'], a.analysis_timeout)
    warnings = run.analyze()
    result = run.result
    if a.grade:
        result['changed_files'] = changes
        result['analyzer_installation'] = analyzer
        result['dependencies'] = dependencies
        if baseline:
            result['baseline'] = baseline
    if warnings is not None:
        result['warnings'] = [brief(w) for w in warnings]
        if a.grade:
            # A warning keeps its key wherever it moves in the file (warning_key).
            original = {warning_key(w, target) for w in TASK['originals']}
            allowed = set(TASK['allowed'])
            remaining = [w for w in warnings if warning_key(w) in original]
            new = [w for w in warnings if warning_key(w) not in original
                   and warning_key(w) not in (allowed if warning_audit_file(target, w.get('file', '')) else elsewhere | set(TASK.get('allowed_elsewhere', [])))]
            result['original_warning_remains'] = [brief(w) for w in remaining]
            result['new_warnings'] = [brief(w) for w in new]
            result['status'] = 'original_warning_remains' if remaining else 'new_warnings' if new else 'passed'
    result['reward'] = int(result['status'] == 'passed')
    (Path(a.logs) / 'result.json').write_text(json.dumps(result, indent=2) + '\n')
    if a.grade:
        print(json.dumps({k: result.get(k) for k in ('status', 'reward', 'original_warning_remains', 'new_warnings')}, indent=2))
        return 0 if result['reward'] else 1
    if warnings is None:
        print('analysis failed: %s (logs in %s)' % (result['status'], a.logs))
        return 1
    print('%d warning(s) in %s' % (len(warnings), TASK['target_file']))
    for w in sorted(warnings, key=lambda w: w.get('line', 0)):
        print('%s:%s: %s in %s\n    %s' % (TASK['target_file'], w.get('line'), w.get('bug_type'), w.get('procedure'), w.get('qualifier')))
    return 0


if __name__ == '__main__':
    sys.exit(main())
'''


def verifier_script() -> bytes:
    """The generated analysis script: the audit's own functions and capture scripts, then VERIFIER_MAIN."""
    import inspect
    head = ('#!/usr/bin/env python3\n"""Generated by patch.py: runs the task\'s static analyzer on the target\n'
            'file the way the warning audit did. analyze.sh (agent) prints the file\'s warnings; the verifier\n'
            'also compares them with the audited ones."""\n'
            'import argparse\nimport json\nimport os\nfrom pathlib import Path, PurePosixPath\nimport re\nimport shutil\nimport signal\nimport tempfile\n'
            'import sqlite3\nimport subprocess\nimport sys\nimport time\n\n')
    constants = ('AUDIT_CAPTURE_SH', 'AUDIT_CAPTURE_PY', 'AUDIT_JAVAC_SHIM', 'AUDIT_INFER_JAVAC', 'AUDIT_CSHARP_BUILD_SH',
                 'AUDIT_NO_REFORMAT', 'AUDIT_UNSKIPPABLE_FORMATTERS', '_AUDIT_SOURCE_ROOT', 'SOURCE_SUFFIXES', 'BUILD_DIRECTORIES', 'ANALYZER_CONFIGURATION',
                 'ANALYZER_ROOTS', 'DEPENDENCY_ARCHIVE', 'DEPENDENCY_MARKER')
    functions = (warning_audit_file, warning_audit_strip_formatters, warning_audit_infersharp_version, warning_audit_legacy_infersharp,
                 warning_audit_assemblies, warning_audit_captured_procedures, analyzer_digest, warning_key)
    values = globals()
    text = head + ''.join('%s = %s\n' % (name, 're.compile(%r)' % values[name].pattern if name == '_AUDIT_SOURCE_ROOT' else repr(values[name]))
                          for name in constants)
    text += ''.join('\n\n' + inspect.getsource(f).rstrip('\n') + '\n' for f in functions)
    return (text + VERIFIER_MAIN).encode()


def collected_result(verifier: Path, target: str, expected: dict | None) -> dict:
    """What pipeline.py needs from a verifier's log directory (/logs/verifier of a trial, under
    whatever runner): the verifier's result, the outcome of the garbage-file build, and which of
    the analyzer's warnings in the target file is the one the dataset names: the same key, or the
    matching rule on type, file, method, line and message (it needs the analyzer's full report)."""
    read = lambda name: (verifier / name).read_text(errors='replace') if (verifier / name).is_file() else None
    result = json.loads(read('result.json') or '{}')
    out = {'status': result.get('status'), 'steps': result.get('steps'), 'compiles': result.get('compiles'), 'result': result}
    if read('poison.exit') is not None:
        out['poison'] = {'exit': read('poison.exit').strip(), 'diagnostics': diagnostics(read('poison.log') or '', target)[:3]}
    if expected and read('report.json') is not None:
        matches = []
        for w in json.loads(read('report.json')):
            if not warning_audit_file(target, w.get('file', '')):
                continue
            same_key = (expected.get('hash') and w.get('hash') == expected['hash']) or warning_key(w) == warning_key(expected, target) != expected.get('hash')
            kind = 'key' if same_key else warning_audit_match(expected, w)
            if kind != 'none':
                matches.append({'hash': w.get('hash'), 'key': warning_key(w), 'bug_type': w.get('bug_type'), 'procedure': w.get('procedure'),
                                'line': w.get('line'), 'qualifier': w.get('qualifier'), 'match': kind})
        out['matches'] = matches
    return out


def task_warnings(task_id: str) -> dict:
    row = embedded_warnings().get(task_id)
    if row is None:
        raise ValueError('no audited warning for ' + task_id)
    return row


# The analyzer release of a task is part of its recipe (`analyzer`, see the end of this file).


def task_analyzer(task) -> str:
    return _ANALYZER.get(task.task_id) or ('Infer 0.17.0' if task.language == 'java' else 'InferSharp 1.3')


